entries[184825] = { ["name"] = "Anhänger: Verteidiger Boros", ["text"] = "Sofort\nDie Hand von Argus war einst ein mächtiger Orden draenischer Paladine, der sich dazu verpflichtet hatte, sein Volk vor den Häschern der Legion zu schützen. Seine Ränge müssen sich jedoch erst von der Dezimierung durch die rasenden Orcs erholen, und Verteidiger Boros weigert sich, ihr Vermächtnis in Vergessenheit geraten zu lassen. Er ist fest entschlossen, die heiligen Schwüre um jeden Preis zu erneuen." }
