entries[184874] = { ["name"] = "Dämonenchakram", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchattenfürst Iskar schleudert ein Dämonenchakram, das von drei Spielercharakteren abprallt, bevor es zu ihm zurückkehrt. Beim Aufschlagen auf diese Ziele löst das Chakram eine Explosion aus, die allen Gegnern abhängig von ihrer Entfernung zur Explosion bis zu 5999 Feuerschaden zufügt. Zusätzlich fügt dieses Chakram allen Spielercharakteren, die es auf dem Weg zum Ziel passiert, 4199 Feuerschaden zu." }
