entries[184909] = { ["name"] = "Strahlendes Licht", ["text"] = "Heilung mit 'Heiliger Schock' gewährt Euch 'Strahlendes Licht', was die Heilung Eurer nächsten Einsätze von 'Heiliges Licht' oder 'Lichtblitz' innerhalb von 6 Sek. um 7 % erhöht." }
entries[184910] = { ["name"] = "Gunst des Retters", ["text"] = "Wenn Eure Gesundheit unter 5 % fällt, wird das Licht Euch um (Angriffskraft * 93 / 100) heilen und Gegnern in der Nähe (Angriffskraft * 93 / 100) Heiligschaden zufügen. Dieser Effekt kann nur einmal alle 12 Sek. auftreten." }
entries[184911] = { ["name"] = "Gebündelte Rache", ["text"] = "'Kreuzfahrerstoß' erhöht Euren Schaden für 10 Sek. um ( 37 / 100)%. Dieser Effekt ist bis zu 3-mal stapelbar und wird zurückgesetzt, wenn Ihr für 'Kreuzfahrerstoß' ein anderes Ziel auswählt." }
entries[184912] = { ["name"] = "Disziplin der Naaru", ["text"] = "'Schattenheilung', 'Bittgebet', 'Machtwort: Glanz' und 'Sühne' verleihen Verbündeten zusätzlich 'Disziplin der Naaru', was den erlittenen Schaden 10 Sek. lang um 1 % verringert." }
entries[184913] = { ["name"] = "Tempo", ["text"] = "Unbegrenzte Reichweite\nSofort\nDas Einsammeln von Teufelsfeuermunition erhöht die Bewegungsgeschwindigkeit 15 Sek. lang um 100%." }
entries[184914] = { ["name"] = "Unversehrtheit", ["text"] = "Erhöht Eure durch 'Heilung' und 'Blitzheilung' hervorgerufene Heilung um 2 %." }
entries[184915] = { ["name"] = "Geistige Ermüdung", ["text"] = "Schaden durch 'Gedankenschinden' belegt das Ziel mit 'Geistige Ermüdung', was den durch Gedankenzauber erlittenen Schaden 10 Sek. lang um ( 73 / 100)% erhöht. Dieser Effekt ist bis zu 5-mal stapelbar." }
entries[184916] = { ["name"] = "Giftmörder", ["text"] = "'Vergiften' erhöht zusätzlich die kritische Trefferchance von 'Verstümmeln' um 4 %." }
entries[184917] = { ["name"] = "Ausweidende Klinge", ["text"] = "Eure Fähigkeit 'Durchstoßen' verursacht nun 7 % zusätzlichen Schaden." }
entries[184918] = { ["name"] = "Aus den Schatten", ["text"] = "Erhöht den Schaden von 'Schattenschlag' um 8 %." }
entries[184919] = { ["name"] = "Elementardonner", ["text"] = "Erhöht den Schaden und die Dauer von 'Flammenschock' um 13 %." }
