entries[184921] = { ["name"] = "Ebbe und Flut", ["text"] = "'Heilende Woge', 'Kettenheilung' oder 'Welle der Heilung', die auf ein Ziel gewirkt werden, das von Eurem Zauber 'Springflut' betroffen ist, haben eine Chance von 5 %, diesen Effekt von 'Springflut' auf einen weiteren Verbündeten in der Nähe auszuweiten." }
entries[184922] = { ["name"] = "Epidemie", ["text"] = "Verringert die Dauer und verkürzt das Tickintervall von 'Agonie', 'Instabiles Gebrechen' und 'Verderbnis' um 2 %." }
