entries[184927] = { ["name"] = "Schildmeisterschaft", ["text"] = "Schutz, Schutz\n'Schildblock' verringert jetzt auch erlittenen Magieschaden um 2 %. 'Zähne zusammenbeißen' erhöht jetzt auch Eure Rüstung um 2 %. 'Schildansturm' erhöht jetzt Schaden durch 'Schildschlag', 'Rache' und 'Heldenhafter Stoß' um zusätzliche 3 %." }
