entries[185099] = { ["name"] = "Tritt der aufgehenden Sonne", ["text"] = "Nahkampfreichweite\nSofort\nWindläufer\nEin hoher Tritt, der [(143.8% der Angriffskraft) * [(Angriffskraft * 0.98)][((Angriffskraft + Schildhand-Angriffskraft) * 2 / 3)] -- 2H, DW / Angriffskraft] körperlichen Schaden verursacht .\n\nNebelwirker\nEin hoher Tritt, der (143.8% der Angriffskraft) körperlichen Schaden verursacht.\n\nBraumeister\nEin hoher Tritt, der (143.8% der Angriffskraft) körperlichen Schaden verursacht.\n\nNebelwirker\nApplies Renewing Mist for 6 seconds to an ally within 40 yds" }
